(function(){
  "use strict";

  const W=window;
  if(W.ZZXMempoolMosaicSorter?.__version>=3)return;

  function finite(value,fallback=-Infinity){
    const n=Number(value);
    return Number.isFinite(n)?n:fallback;
  }

  function hash32(text,seed=0){
    let h=(seed>>>0)^0x9e3779b9;
    const s=String(text||"");

    for(let i=0;i<s.length;i++){
      h=Math.imul(h^s.charCodeAt(i),0x01000193);
      h^=h>>>13;
    }

    return h>>>0;
  }

  function sort(items,mode="priority",seed=0){
    const rows=(Array.isArray(items)?items:[]).slice();

    const comparator=(a,b)=>{
      if(mode==="fee"){
        return finite(b.packageFeeRate??b.feeRate)-finite(a.packageFeeRate??a.feeRate);
      }

      if(mode==="size"){
        return finite(b.vsize)-finite(a.vsize);
      }

      if(mode==="value"){
        return finite(b.valueSats)-finite(a.valueSats);
      }

      if(mode==="age"){
        return finite(a.firstSeen,Infinity)-finite(b.firstSeen,Infinity);
      }

      if(mode==="rbf"){
        const ar=a.rbf?1:0;
        const br=b.rbf?1:0;
        if(br!==ar)return br-ar;
      }

      if(mode==="type"){
        const at=String(a.type||"");
        const bt=String(b.type||"");
        const c=at.localeCompare(bt);
        if(c)return c;
      }

      if(mode==="shuffle"){
        return hash32(a.txid,seed)-hash32(b.txid,seed);
      }

      const ar=finite(a.rank,Number.MAX_SAFE_INTEGER);
      const br=finite(b.rank,Number.MAX_SAFE_INTEGER);
      if(ar!==br)return ar-br;

      const af=finite(a.packageFeeRate??a.feeRate);
      const bf=finite(b.packageFeeRate??b.feeRate);
      if(bf!==af)return bf-af;

      return String(a.txid).localeCompare(String(b.txid));
    };

    return rows.sort(comparator);
  }

  W.ZZXMempoolMosaicSorter=Object.freeze({
    __version:3,
    hash32,
    sort
  });
})();


// mempool-mosaic/js/mosaic-packer.js
// v3 — 3x3-dominant exact-cover square mosaic geometry.
(function(){
  "use strict";

  const W=window;
  if(W.ZZXMempoolMosaicPacker?.__version>=3)return;

  const EPS=1e-12;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));

  // Replacing one square with a 2x2 adds 3 leaves; replacing one with a 3x3
  // adds 8. Therefore every exact recursive mosaic has N = 1 + 3a + 8b.
  function representation(count,targetThreeRatio=.68){
    const n=Math.max(1,Math.floor(Number(count)||1));
    if(n===1)return {a:0,b:0,score:0};
    const remainder=n-1;
    let best=null;
    for(let b=0;b<=Math.floor(remainder/8);b++){
      const left=remainder-b*8;
      if(left<0||left%3)continue;
      const a=left/3;
      const ops=a+b;
      const ratio=ops?b/ops:0;
      // Mosaic intentionally favors 3x3 subdivision. A shallow penalty keeps
      // the result cellular instead of degenerating into one very deep branch.
      const score=Math.abs(ratio-targetThreeRatio)+(ops?Math.max(0,a-b)*.001:0);
      if(!best||score<best.score)best={a,b,score};
    }
    return best;
  }

  function isConstructible(count){return Boolean(representation(count));}

  function nextConstructible(count){
    const start=Math.max(1,Math.floor(Number(count)||1));
    for(let n=start;n<start+24;n++)if(isConstructible(n))return n;
    return start;
  }

  function cellOrder(grid,depth,seed){
    // Stable serpentine raster with deterministic quarter-turns. Unlike Tiles'
    // atlas ordering this produces locally coherent mosaic neighborhoods.
    const out=[];
    const rotate=(seed+depth)%4;
    for(let y=0;y<grid;y++){
      const reverse=(y+(seed&1))%2===1;
      for(let step=0;step<grid;step++){
        let x=reverse?grid-1-step:step;
        let yy=y,xx=x;
        if(rotate===1){xx=grid-1-y;yy=x;}
        else if(rotate===2){xx=grid-1-x;yy=grid-1-y;}
        else if(rotate===3){xx=y;yy=grid-1-x;}
        out.push({x:xx,y:yy});
      }
    }
    return out;
  }

  function distributeOperations(k,a,b,depth,seed){
    const bundles=Array.from({length:k},(_,index)=>({index,a:0,b:0,count:1}));
    const order=cellOrder(Math.round(Math.sqrt(k)),depth,seed).map(p=>p.y*Math.round(Math.sqrt(k))+p.x);
    const sequence=[];

    // 3x3 splits are placed first and spread spatially; 2x2 splits then fill
    // the remaining detail. This is deliberately different from Tiles' weighted
    // bundle allocator and creates the characteristic coarse mosaic texture.
    for(let i=0;i<b;i++)sequence.push({key:"b",inc:8,phase:i});
    for(let i=0;i<a;i++)sequence.push({key:"a",inc:3,phase:i+b});

    for(const op of sequence){
      let winner=order[op.phase%order.length]??0;
      let best=Infinity;
      for(let j=0;j<k;j++){
        const idx=order[(op.phase+j)%order.length]??j;
        const bundle=bundles[idx];
        // Prefer shallower bundles to avoid hairline cells and keep the mosaic
        // visually distributed across the whole block.
        const score=bundle.count + (bundle.a+bundle.b)*.35 + j*1e-6;
        if(score<best){best=score;winner=idx;}
      }
      bundles[winner][op.key]++;
      bundles[winner].count+=op.inc;
    }
    return bundles;
  }

  function chooseGrid(a,b,depth,seed){
    if(b<=0)return 2;
    if(a<=0)return 3;
    // Strong 3x3 preference, with occasional 2x2 punctuation so leaf sizes are
    // varied enough to communicate transaction magnitude.
    return ((depth*5+(seed&7))%7)<5?3:2;
  }

  function buildNode(a,b,x,y,side,depth,seed,leaves,nodes){
    if(a<=0&&b<=0){
      const leaf={x,y,side,depth,children:null,item:null};
      leaves.push(leaf);
      nodes.push(leaf);
      return leaf;
    }

    let grid=chooseGrid(a,b,depth,seed);
    if(grid===3&&b<=0)grid=2;
    if(grid===2&&a<=0)grid=3;

    const nextA=a-(grid===2?1:0);
    const nextB=b-(grid===3?1:0);
    const k=grid*grid;
    const bundles=distributeOperations(k,nextA,nextB,depth,seed);
    const cells=cellOrder(grid,depth,seed);
    const childSide=side/grid;
    const children=[];
    const node={x,y,side,depth,grid,children,item:null};
    nodes.push(node);

    for(let i=0;i<k;i++){
      const cell=cells[i];
      const bundle=bundles[i];
      children.push(buildNode(
        bundle.a,bundle.b,
        x+cell.x*childSide,
        y+cell.y*childSide,
        childSide,
        depth+1,
        (Math.imul(seed^((i+1)*0x9e3779b1),1664525)+1013904223)>>>0,
        leaves,nodes
      ));
    }
    return node;
  }

  function hit(node,nx,ny){
    if(!node||nx<node.x-EPS||ny<node.y-EPS||nx>node.x+node.side+EPS||ny>node.y+node.side+EPS)return null;
    let current=node;
    while(current?.children?.length){
      let found=null;
      for(const child of current.children){
        if(nx>=child.x-EPS&&nx<=child.x+child.side+EPS&&ny>=child.y-EPS&&ny<=child.y+child.side+EPS){found=child;break;}
      }
      if(!found)break;
      current=found;
    }
    return current?.item||null;
  }

  function pack(count,{seed=0}={}){
    const sourceCount=Math.max(0,Math.floor(Number(count)||0));
    if(!sourceCount)return {root:null,leaves:[],nodes:[],sourceCount:0,leafCount:0,fragmentCount:0,maxDepth:0,coverage:0};
    const leafCount=nextConstructible(sourceCount);
    const plan=representation(leafCount);
    const leaves=[];
    const nodes=[];
    const root=buildNode(plan.a,plan.b,0,0,1,0,Number(seed)>>>0,leaves,nodes);
    const coverage=leaves.reduce((sum,leaf)=>sum+leaf.side*leaf.side,0);
    return {
      root,leaves,nodes,
      sourceCount,
      leafCount:leaves.length,
      fragmentCount:leaves.length-sourceCount,
      maxDepth:leaves.reduce((m,l)=>Math.max(m,l.depth||0),0),
      coverage:clamp(coverage,0,1+EPS),
      plan:{a:plan.a,b:plan.b,targetThreeRatio:.68}
    };
  }

  W.ZZXMempoolMosaicPacker=Object.freeze({
    __version:3,
    representation,
    isConstructible,
    nextConstructible,
    cellOrder,
    pack,
    hit
  });
})();


// mempool-mosaic/js/layout.js
// v6 — metric-to-square mosaic adapter with local fee/priority neighborhoods.
(function(){
  "use strict";

  const W=window;
  if(W.ZZXMempoolMosaicLayout?.__version>=6)return;

  const S=()=>W.ZZXMempoolMosaicScaler;
  const Sorter=()=>W.ZZXMempoolMosaicSorter;
  const P=()=>W.ZZXMempoolMosaicPacker;
  const EPS=1e-12;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));

  function metric(tx,mode){
    const value=Number(S().metricValue(tx,mode));
    return Number.isFinite(value)?value:-Infinity;
  }

  function spatialCompare(a,b){
    // Serpentine scan by leaf center. It deliberately groups same-sized cells
    // into contiguous neighborhoods rather than the atlas-like placement used
    // by Mempool Tiles.
    const ay=Math.round((a.y+a.side/2)*1e9);
    const by=Math.round((b.y+b.side/2)*1e9);
    if(ay!==by)return ay-by;
    const row=Math.floor((a.y+a.side/2)*4096);
    const ax=a.x+a.side/2,bx=b.x+b.side/2;
    return row%2?bx-ax:ax-bx;
  }

  function groupLeaves(leaves){
    const ordered=leaves.slice().sort((a,b)=>b.side-a.side||spatialCompare(a,b));
    const groups=[];
    for(const leaf of ordered){
      const prior=groups.at(-1);
      if(prior&&Math.abs(prior.side-leaf.side)<EPS)prior.leaves.push(leaf);
      else groups.push({side:leaf.side,leaves:[leaf]});
    }
    return groups;
  }

  function neighborhoodOrder(rows,sortMode,seed){
    if(sortMode&&sortMode!=="mosaic")return Sorter().sort(rows,sortMode,seed);
    return rows.slice().sort((a,b)=>{
      const af=Number(a.packageFeeRate??a.feeRate);
      const bf=Number(b.packageFeeRate??b.feeRate);
      if(Number.isFinite(af)&&Number.isFinite(bf)&&bf!==af)return bf-af;
      const av=Number(a.valueSats),bv=Number(b.valueSats);
      if(Number.isFinite(av)&&Number.isFinite(bv)&&bv!==av)return bv-av;
      const ar=Number(a.rank),br=Number(b.rank);
      if(Number.isFinite(ar)&&Number.isFinite(br)&&ar!==br)return ar-br;
      return Sorter().hash32(a.txid,seed)-Sorter().hash32(b.txid,seed);
    });
  }

  function collectGuides(node,out=[]){
    if(!node?.children?.length)return out;
    if((node.depth||0)<=2)out.push({x:node.x,y:node.y,side:node.side,depth:node.depth,grid:node.grid});
    for(const child of node.children)collectGuides(child,out);
    return out;
  }

  function build(model,{scaleMode="value",sortMode="mosaic",seed=0}={}){
    const source=(model?.candidate||[]).filter(tx=>tx?.txid);
    if(!source.length){
      return {schema:"zzx-mempool-mosaic-v3",tiles:[],byTxid:new Map(),root:null,guides:[],sourceCount:0,leafCount:0,fragmentCount:0,levels:0,exactCover:true,coverage:0,scale:null,vsizeScale:null,scaleMode,sortMode,seed,builtAt:Date.now()};
    }

    const scale=S().makeScale(source,scaleMode);
    const vsizeScale=S().makeScale(source,"vsize");
    const packed=P().pack(source.length,{seed});
    const groups=groupLeaves(packed.leaves);

    // Size assignment is monotonic: larger selected metrics always consume a
    // leaf at least as large as a smaller metric. Equal-size leaves are then
    // ordered spatially by the selected neighborhood mode.
    const metricSorted=source.slice().sort((a,b)=>{
      const av=metric(a,scaleMode),bv=metric(b,scaleMode);
      if(bv!==av)return bv-av;
      return String(a.txid).localeCompare(String(b.txid));
    });

    const fragmentSource=metricSorted.slice().reverse();
    const tiles=[];
    let cursor=0,fragmentCursor=0;

    for(const group of groups){
      const realCount=Math.min(group.leaves.length,Math.max(0,source.length-cursor));
      const realRows=neighborhoodOrder(metricSorted.slice(cursor,cursor+realCount),sortMode,seed);
      cursor+=realCount;
      const leaves=group.leaves.slice().sort(spatialCompare);

      for(let i=0;i<leaves.length;i++){
        const leaf=leaves[i];
        const fragment=i>=realCount;
        const base=fragment
          ? fragmentSource[(fragmentCursor++)%fragmentSource.length]
          : realRows[i];
        const tile={
          ...base,
          x:leaf.x,y:leaf.y,side:leaf.side,
          cx:leaf.x+leaf.side/2,cy:leaf.y+leaf.side/2,
          area:leaf.side*leaf.side,
          footprint:S().normalized(base,scale),
          vsizeNorm:S().normalized(base,vsizeScale),
          leafDepth:Number(leaf.depth)||0,
          index:tiles.length,
          __fragment:fragment,
          __fragmentIndex:fragment?fragmentCursor:0
        };
        leaf.item=tile;
        tiles.push(tile);
      }
    }

    const byTxid=new Map();
    for(const tile of tiles)if(!tile.__fragment&&!byTxid.has(tile.txid))byTxid.set(tile.txid,tile);
    for(const tile of tiles)if(!byTxid.has(tile.txid))byTxid.set(tile.txid,tile);

    return {
      schema:"zzx-mempool-mosaic-v3",
      tiles,byTxid,root:packed.root,
      guides:collectGuides(packed.root),
      sourceCount:source.length,
      leafCount:tiles.length,
      fragmentCount:packed.fragmentCount,
      levels:packed.maxDepth,
      exactCover:true,
      coverage:clamp(packed.coverage,0,1),
      scale,vsizeScale,scaleMode,sortMode,seed,
      plan:packed.plan,
      builtAt:Date.now()
    };
  }

  function hit(layout,x,y){
    if(!layout?.root)return null;
    return P().hit(layout.root,clamp(Number(x)||0,0,1-Number.EPSILON),clamp(Number(y)||0,0,1-Number.EPSILON));
  }

  W.ZZXMempoolMosaicLayout=Object.freeze({__version:6,build,hit});
})();


